/* 最小化游戏初始化脚本 */
import * as Phaser from 'phaser';
import { GRID_SIZE } from './constants.js';
import { setupInput } from './input.js';
import { player } from './player.js';

export class GameScene extends Phaser.Scene {
  constructor() {
    super({ key: 'GameScene' });
  }

  preload() {
    this.load.image('grass', 'images/map-grass.png');
    this.load.image('stone', 'images/barrier-stone.png');
    this.load.spritesheet('player', 'images/行走圖-主角.png', {
      frameWidth: 32,
      frameHeight: 32
    });
  }

  create() {
    // 创建基本地图
    const size = 64;
    const tileSize = GRID_SIZE;
    const ground = Array(size).fill().map(() => Array(size).fill(1));
    const objectLayer = Array(size).fill().map(() => Array(size).fill(0));

    // 添加迷宫障碍物（更复杂的迷宫逻辑）
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        // 创建迷宫墙壁
        if (x === 0 || y === 0 || x === size-1 || y === size-1) {
          objectLayer[y][x] = 2; // 边界墙
        } else if (x % 2 === 0 && y % 2 === 0) {
          objectLayer[y][x] = 2; // 固定墙
        } else if (Math.random() > 0.7) {
          objectLayer[y][x] = 2; // 随机墙
        }
      }
    }
    
    // 确保玩家起始位置是空的
    const startX = Math.floor(size/2);
    const startY = Math.floor(size/2);
    objectLayer[startY][startX] = 0;
    objectLayer[startY-1][startX] = 0;
    objectLayer[startY][startX-1] = 0;

    // 渲染地图
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        // 添加草地
        this.add.image(x * tileSize, y * tileSize, 'grass')
          .setDisplaySize(tileSize, tileSize)
          .setDepth(-30);
        
        // 添加障碍物
        if (objectLayer[y][x] === 2) {
          this.add.image(x * tileSize, y * tileSize, 'stone')
            .setDisplaySize(tileSize, tileSize)
            .setDepth(-10);
        }
      }
    }

    // 创建玩家并确保显示
    player.sprite = this.add.sprite(
      startX * tileSize,
      startY * tileSize,
      'player'
    ).setOrigin(0.5, 0.5); // 设置中心点为精灵中心
    
    // 设置显示大小为基本单位的2倍
    const displaySize = tileSize * 2;
    player.sprite.setDisplaySize(displaySize, displaySize);
    player.sprite.setDepth(10); // 确保玩家在最上层
    
    // 添加玩家动画
    this.anims.create({
      key: 'player-idle',
      frames: this.anims.generateFrameNumbers('player', { start: 0, end: 3 }),
      frameRate: 10,
      repeat: -1
    });
    player.sprite.play('player-idle');

    // 设置玩家动画
    this.anims.create({
      key: 'player-idle',
      frames: this.anims.generateFrameNumbers('player', { start: 0, end: 3 }),
      frameRate: 10,
      repeat: -1
    });
    player.sprite.play('player-idle');

    // 设置输入控制
    setupInput(this);
  }

  update() {
    // 简单的玩家移动逻辑
    if (player.moveDirection) {
      player.sprite.x += player.moveDirection.x * player.speed;
      player.sprite.y += player.moveDirection.y * player.speed;
    }
  }
}

// 初始化游戏
const config = {
  type: Phaser.AUTO,
  width: window.innerWidth,
  height: window.innerHeight,
  scene: [GameScene],
  parent: 'game-container',
  scale: {
    mode: Phaser.Scale.RESIZE,
    autoCenter: Phaser.Scale.CENTER_BOTH
  },
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { y: 0 },
      debug: false
    }
  }
};

const game = new Phaser.Game(config);